using Autodesk.Revit.UI;
using Autodesk.Revit.UI.Events;
using System.IO;
using System.Reflection;
using System.Windows.Media.Imaging;

namespace DxfToRevit.Addin;

/// <summary>
/// Revit application entry point: creates the "DxfToRevit" ribbon tab with the Import DXF,
/// Settings and About buttons.
/// </summary>
/// <remarks>
/// Button icons follow the Revit UI theme (light or dark) and are swapped automatically when the
/// theme changes. Icon files: <c>Resources/&lt;Name&gt;_&lt;Light|Dark&gt;_&lt;16|32&gt;.png</c>
/// (generated by <c>scripts/IconGenerator</c>).
/// </remarks>
public sealed class DxfToRevitApplication : IExternalApplication
{
    private const string TabName = "DxfToRevit";
    private const string PanelName = "DXF Import";

    /// <summary>Created buttons and their icon base names (reloaded when the theme changes).</summary>
    private readonly List<(PushButton Button, string IconName)> _themedButtons = new();

    /// <summary>Folder that holds the ribbon icons.</summary>
    private string _resourceDirectory = string.Empty;

    /// <summary>Creates the ribbon tab, panel and buttons and subscribes to theme changes.</summary>
    /// <param name="application">Revit UI application.</param>
    /// <returns>Always <see cref="Result.Succeeded"/>.</returns>
    public Result OnStartup(UIControlledApplication application)
    {
        try
        {
            application.CreateRibbonTab(TabName);
        }
        catch (Autodesk.Revit.Exceptions.ArgumentException)
        {
            // The tab already exists.
        }

        RibbonPanel panel = application.CreateRibbonPanel(TabName, PanelName);
        string assemblyPath = Assembly.GetExecutingAssembly().Location;
        _resourceDirectory = Path.Combine(Path.GetDirectoryName(assemblyPath) ?? string.Empty, "Resources");

        AddButton(panel, assemblyPath, "ImportDxf", "Import\nDXF",
            typeof(ImportDxfCommand), "Import walls, columns, doors, windows and openings from a DXF drawing.",
            "ImportDxf");

        AddButton(panel, assemblyPath, "ColumnSettings", "Settings",
            typeof(ColumnSettingsCommand),
            "Choose what to import, the levels, the column options and the door and window types.",
            "Settings");

        AddButton(panel, assemblyPath, "AboutDxfToRevit", "About",
            typeof(AboutCommand), "About DxfToRevit: DXF import of walls, columns, doors, windows and openings.",
            "About");

        application.ThemeChanged += OnThemeChanged;

        return Result.Succeeded;
    }

    /// <summary>Unsubscribes from theme changes.</summary>
    /// <param name="application">Revit UI application.</param>
    /// <returns>Always <see cref="Result.Succeeded"/>.</returns>
    public Result OnShutdown(UIControlledApplication application)
    {
        application.ThemeChanged -= OnThemeChanged;
        return Result.Succeeded;
    }

    /// <summary>Reloads every button icon for the new theme.</summary>
    private void OnThemeChanged(object? sender, ThemeChangedEventArgs e)
    {
        string theme = CurrentThemeSuffix();
        foreach (var (button, iconName) in _themedButtons)
            ApplyIcons(button, iconName, theme);
    }

    /// <summary>Adds a push button for <paramref name="commandType"/> and applies its theme icons.</summary>
    private void AddButton(
        RibbonPanel panel,
        string assemblyPath,
        string name,
        string text,
        Type commandType,
        string tooltip,
        string iconName)
    {
        var data = new PushButtonData(name, text, assemblyPath, commandType.FullName!)
        {
            ToolTip = tooltip
        };

        if (panel.AddItem(data) is PushButton button)
        {
            ApplyIcons(button, iconName, CurrentThemeSuffix());
            _themedButtons.Add((button, iconName));
        }
    }

    /// <summary>Sets the 16 px and 32 px icons of a button for the given theme.</summary>
    private void ApplyIcons(PushButton button, string iconName, string theme)
    {
        BitmapImage? small = TryLoadIcon(iconName, theme, 16);
        BitmapImage? large = TryLoadIcon(iconName, theme, 32);
        if (small is not null)
            button.Image = small;
        if (large is not null)
            button.LargeImage = large;
    }

    /// <summary>Current Revit UI theme as an icon suffix: "Dark" for the dark theme, otherwise "Light".</summary>
    private static string CurrentThemeSuffix()
    {
        try
        {
            return UIThemeManager.CurrentTheme == UITheme.Dark ? "Dark" : "Light";
        }
        catch
        {
            return "Light";
        }
    }

    /// <summary>
    /// Loads <c>&lt;name&gt;_&lt;theme&gt;_&lt;size&gt;.png</c>; falls back to the light icon when the theme
    /// variant is missing, and returns <c>null</c> when neither exists.
    /// </summary>
    private BitmapImage? TryLoadIcon(string iconName, string theme, int size)
    {
        string path = Path.Combine(_resourceDirectory, $"{iconName}_{theme}_{size}.png");
        if (!File.Exists(path))
        {
            // Theme variant missing: fall back to the light icon.
            path = Path.Combine(_resourceDirectory, $"{iconName}_Light_{size}.png");
            if (!File.Exists(path))
                return null;
        }

        var image = new BitmapImage();
        image.BeginInit();
        image.UriSource = new Uri(path, UriKind.Absolute);
        image.CacheOption = BitmapCacheOption.OnLoad;
        image.EndInit();
        image.Freeze();
        return image;
    }
}
